export function stringNode(value) {
  return { kind: 'scalar', tag: 'str', value };
}

export function nullNode() {
  return { kind: 'scalar', tag: 'null', value: null };
}

export function boolNode(value) {
  return { kind: 'scalar', tag: 'bool', value: value ? true : false };
}

export function intNode(text, numericValue) {
  return { kind: 'scalar', tag: 'int', value: text, numericValue };
}

export function floatNode(text, numericValue, negativeZero = false) {
  return { kind: 'scalar', tag: 'float', value: text, numericValue, negativeZero };
}

export function timestampNode(text) {
  return { kind: 'scalar', tag: 'timestamp', value: text };
}

export function seqNode(items) {
  return { kind: 'seq', items };
}

export function mapNode(entries) {
  return { kind: 'map', entries };
}

