function scriptName(pathText) {
  if (!pathText) {
    return 'test13.mjs';
  }
  const slash = pathText.lastIndexOf('/');
  if (slash === -1) {
    return pathText;
  }
  return pathText.slice(slash + 1);
}

function usage(name) {
  return `usage: ${name} [-h] --a A`;
}

function helpText(name) {
  return `${usage(name)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function looksLikeNegativeNumber(token) {
  if (!token || token.length < 2 || token[0] !== '-') {
    return false;
  }
  let sawDigit = false;
  let sawDot = false;
  for (let index = 1; index < token.length; index += 1) {
    const char = token[index];
    if (char >= '0' && char <= '9') {
      sawDigit = true;
      continue;
    }
    if (char === '.' && !sawDot) {
      sawDot = true;
      continue;
    }
    return false;
  }
  return sawDigit;
}

function writeStdout(text) {
  process.stdout.write(text);
}

function writeStderr(text) {
  process.stderr.write(text);
}

function fail(name, message) {
  writeStderr(`${usage(name)}\n`);
  writeStderr(`${name}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv, executablePath) {
  const name = scriptName(executablePath);
  let value = null;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === '-h' || token === '--help') {
      writeStdout(helpText(name));
      process.exit(0);
    }
    if (token === '--a') {
      if (index + 1 >= argv.length) {
        fail(name, 'argument --a: expected one argument');
      }
      const next = argv[index + 1];
      if ((next === '-h' || next === '--help' || next === '--') || (next.startsWith('-') && !looksLikeNegativeNumber(next))) {
        fail(name, 'argument --a: expected one argument');
      }
      value = next;
      index += 1;
      continue;
    }
    extras.push(token);
  }

  if (value === null) {
    fail(name, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail(name, `unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: value };
}

